-- Resources content for Bookings' second slice, the term plan and the
-- calendar (CLAUDE.md, "Resources stay in step with the code"). Content
-- only; the schema is 20261005150000_bookings_term_plan.sql.

select private.rc_release_guide(
  p_slug => 'bookings-calendar',
  p_tool_key => 'bookings',
  p_title => 'The calendar and the term plan',
  p_summary => 'The term plan''s two envelopes, each pool''s units and windows, blackouts and holds, bookings, and the booking rule.',
  p_screen_keys => array['bookings.calendar'],
  p_sort_order => 30,
  p_version_note => 'Calendar and term plan',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Calendar","marks":[{"type":"bold"}]},{"type":"text","text":" tab shows one term of production work: what WUWF has kept for itself, what partners have booked, and how much of the term's capacity is left. Everything on it is measured in professional hours; a project day is eight."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The term plan"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Director of Operations creates a term plan from "},{"type":"text","text":"Term plan","marks":[{"type":"bold"}]},{"type":"text","text":": the term's dates, its net professional hours, the reserve share kept for strategic work, the airtime minutes a week the station contributes, and the production lead's hours a day. One plan is active at a time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each pool (studio, field, live, edit) has its units for the term and the windows a booking may take, such as a studio morning or afternoon. Select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" on a pool's row to change them."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The two envelopes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Production capacity","marks":[{"type":"bold"}]},{"type":"text","text":" shows net capacity, the reserve left for strategic work, what is spoken for (bookings and holds) and open capacity. Open capacity is net minus the reserve, minus holds, minus incremental and external bookings. Open the month table to see how it is spread across the term."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Airtime envelope","marks":[{"type":"bold"}]},{"type":"text","text":" is read from On Air's clocks: the avails marked as admitting a university announcement, the minutes the station already pins there, the contributed envelope from the term plan, and what is left for Traffic to sell. Airtime is placed in Traffic or On Air, never here."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Blackouts, holds and bookings"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"blackout","marks":[{"type":"bold"}]},{"type":"text","text":" closes dates to partner work on some or every pool, with a reason. A "},{"type":"text","text":"hold","marks":[{"type":"bold"}]},{"type":"text","text":" is WUWF's own use of one window, core work or maintenance, and takes the lead's hours for that day. The director adds both with "},{"type":"text","text":"+ Blackout","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"+ Hold","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"booking","marks":[{"type":"bold"}]},{"type":"text","text":" is a partner's hold on one window. The production lead or the director adds one with "},{"type":"text","text":"+ Booking","marks":[{"type":"bold"}]},{"type":"text","text":". A tentative booking holds the window for 14 days and counts as taken; confirm it or release it from the list under the calendar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find a slot","marks":[{"type":"bold"}]},{"type":"text","text":" runs the booking rule for a window without booking it, and names the nearest open windows when the one asked for is not available."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The booking rule"}]},{"type":"paragraph","content":[{"type":"text","text":"Every booking is checked in this order: the date is not blacked out or held for WUWF; the window is free, with tentative bookings counted as taken; the lead's day has room for the hours; and the pricing has capacity. A strategic booking draws the reserve; an incremental or external one draws open capacity. A booking that would take more than half of a month's remaining open hours warns but is not refused. Only the Executive Director can record an exception, and each one is written to the audit log."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-05-bookings-calendar',
  p_tool_key => 'bookings',
  p_released_on => '2026-10-05',
  p_title => 'Bookings: the term plan and the calendar',
  p_guide_slugs => array['bookings-calendar'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bookings gains a Calendar tab. The Director of Operations sets up a term plan with the term's net professional hours, the reserve, the contributed airtime and each pool's units and windows, then keeps WUWF's own blackouts and holds on the calendar. The production lead books windows for partner work, and every booking is checked against the same rule: not blacked out or held, the window free, room in the lead's day, and capacity for its pricing. The airtime envelope is read from On Air's clocks and shows what is left for Traffic to sell."}]}]}$body$
);
